def _workspace_id(workspace: Path) -> str:
    return sha256_canonical({"workspace_root": str(workspace)})


def _is_inside(child: Path, parent: Path) -> bool:
    try:
        child.resolve().relative_to(parent.resolve())
        return True
    except ValueError:
        return False


def _known_session_lock(name: str) -> bool:
    if name == WORKSPACE_LOCK_NAME:
        return True
    if name.endswith(".lock") and HEX64.fullmatch(name[: -len(".lock")]):
        return True
    return False


def _classify_workflow(workspace: Path, *, held_workspace_lock: bool) -> dict[str, Any]:
    root = workspace / WORKFLOW_DIRNAME
    exclude: list[str] = []
    remap_prefix = f"{WORKFLOW_DIRNAME}/{SESSIONS_DIRNAME}/"
    include_from_sessions: list[str] = []
    if not os.path.lexists(root):
        return {"kind": "absent", "exclude": exclude, "session_files": include_from_sessions, "message": None}
    if root.is_symlink() or not root.is_dir():
        return {"kind": "unsafe", "exclude": [], "session_files": [], "message": ".light-workflow is not a regular directory"}
    locks = root / LOCKS_DIRNAME
    if os.path.lexists(locks):
        if locks.is_symlink() or not locks.is_dir():
            return {"kind": "unsafe", "exclude": [], "session_files": [], "message": "workflow locks path is not a regular directory"}
        for item in sorted(locks.iterdir(), key=lambda path: path.name):
            relative = f"{WORKFLOW_DIRNAME}/{LOCKS_DIRNAME}/{item.name}"
            if item.is_symlink() or not item.is_file() or not _known_session_lock(item.name):
                return {"kind": "unknown", "exclude": [], "session_files": [], "message": f"unrecognized workflow lock {relative}"}
            held = lock_is_held(item)
            if item.name == WORKSPACE_LOCK_NAME and held_workspace_lock:
                held = False
            if held:
                return {"kind": "pending", "exclude": [], "session_files": [], "message": f"active workflow lock {relative}"}
            exclude.append(relative)
    staging = root / WORKFLOW_STAGING
    if os.path.lexists(staging):
        if staging.is_symlink() or not staging.is_dir():
            return {"kind": "unsafe", "exclude": [], "session_files": [], "message": "workflow staging is not a regular directory"}
        if list_names(staging):
            return {"kind": "pending", "exclude": [], "session_files": [], "message": "pending or unknown workflow staging must be resolved before backup"}
        exclude.append(f"{WORKFLOW_DIRNAME}/{WORKFLOW_STAGING}")
    sessions = root / SESSIONS_DIRNAME
    if os.path.lexists(sessions):
        if sessions.is_symlink() or not sessions.is_dir():
            return {"kind": "unsafe", "exclude": [], "session_files": [], "message": "workflow sessions path is not a regular directory"}
        for item in sorted(sessions.iterdir(), key=lambda path: path.name):
            rel = f"{WORKFLOW_DIRNAME}/{SESSIONS_DIRNAME}/{item.name}"
            if item.is_symlink() or not item.is_dir() or not HEX64.fullmatch(item.name):
                return {"kind": "unknown", "exclude": [], "session_files": [], "message": f"unknown session entry {rel}"}
            lock_path = workspace / WORKFLOW_DIRNAME / LOCKS_DIRNAME / f"{item.name}.lock"
            if is_regular_file(lock_path) and lock_is_held(lock_path):
                return {"kind": "pending", "exclude": [], "session_files": [], "message": f"active completion lock for session {item.name}"}
            names = set(list_names(item))
            extras = names - SESSION_NAMES
            if extras:
                return {"kind": "unknown", "exclude": [], "session_files": [], "message": f"session {item.name} contains unsupported extra files"}
            required = {"request.json", "context.json", "manifest.json"}
            if names and not required <= names and names - required:
                # allow incomplete prepared set only when the present names are allowed session documents
                pass
            for name in sorted(names):
                child = item / name
                classified = classify_text_file(child, label=f"{rel}/{name}")
                if classified["kind"] != "ok":
                    return {"kind": "unknown", "exclude": [], "session_files": [], "message": classified.get("reason") or f"session file is unsafe: {rel}/{name}"}
                include_from_sessions.append(f"{rel}/{name}")
    return {"kind": "ok", "exclude": exclude, "session_files": include_from_sessions, "message": None, "remap_prefix": remap_prefix}


def _snapshot_workspace(workspace: Path, *, extra_outputs: list[Path], held_workspace_lock: bool) -> dict[str, Any]:
    blockers = library_backup_blockers(workspace)
    if blockers is not None:
        return blockers
    if knowledge_staging_nonempty(workspace):
        return closed(
            LIGHT_BACKUP_INVALID,
            "nonempty knowledge staging must be recovered by retrying import/build before backup",
        )
    index = classify_index_tree(workspace)
    if index["kind"] in {"unknown", "unsafe"}:
        return closed(LIGHT_BACKUP_INVALID, index.get("message") or "index tree is not a recognized rebuildable tree")
    transactions = classify_transaction_tree(workspace)
    if transactions["kind"] in {"pending", "unknown", "unsafe"}:
        return closed(LIGHT_BACKUP_INVALID, transactions.get("message") or "transaction tree is unsafe")
    workflow = _classify_workflow(workspace, held_workspace_lock=held_workspace_lock)
    if workflow["kind"] not in {"ok", "absent"}:
        return closed(LIGHT_BACKUP_INVALID, workflow.get("message") or "workflow tree is unsafe")

    exclude_set = set(index.get("exclude") or []) | set(transactions.get("exclude") or []) | set(workflow.get("exclude") or [])
    workspace_id = _workspace_id(workspace)
    remap_to = f"{WORKFLOW_DIRNAME}/{HISTORY_DIRNAME}/{workspace_id}/{SESSIONS_DIRNAME}/"
    files: list[dict[str, Any]] = []
    exclusions: list[dict[str, str]] = []

    if path.exists():
        if not path.is_dir():
            _raise(LIGHT_KNOWLEDGE_CONFLICT, "managed path must be a regular directory", {"path": str(path)})
        return
    if path == stop_at:
        _raise(WORKSPACE_INVALID, "workspace_root must be a regular directory")
    _ensure_regular_dir(path.parent, stop_at=stop_at)
    path.mkdir(exist_ok=True)
    if path.is_symlink() or not path.is_dir():
        _raise(LIGHT_KNOWLEDGE_CONFLICT, "managed path must be a regular directory", {"path": str(path)})


def _load_persisted_object(path: Path) -> dict[str, Any] | None:
    if path.is_symlink() or not path.is_file() or _hardlinked(path):
        return None
    raw = path.read_bytes()
    try:
        value = json.loads(raw.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError):
        return None
    if type(value) is not dict:
        return None
    try:
        if raw != persisted_bytes(value):
            return None
    except ResearchError:
        return None
    return value


def _write_bytes(path: Path, data: bytes) -> None:
    path.write_bytes(data)


def _file_row(relative: str, data: bytes) -> dict[str, Any]:
    return {"path": relative, "sha256": sha256_bytes(data), "size_bytes": len(data)}


def _exact_keys(value: object, keys: set[str]) -> bool:
    return type(value) is dict and set(value) == keys


def _valid_file_row(row: object) -> bool:
    if not _exact_keys(row, {"path", "sha256", "size_bytes"}):
        return False
    assert type(row) is dict
    return (
        type(row["path"]) is str
        and type(row["sha256"]) is str
        and HEX64.fullmatch(row["sha256"]) is not None
        and type(row["size_bytes"]) is int
        and row["size_bytes"] >= 0
    )


def _valid_paper_snapshot(value: object) -> bool:
    if not _exact_keys(value, {"markdown_sha256", "paper_id", "source_json_sha256"}):
        return False
    assert type(value) is dict
    return (
        type(value["markdown_sha256"]) is str
        and HEX64.fullmatch(value["markdown_sha256"]) is not None
        and type(value["paper_id"]) is str
        and PAPER_ID_PATTERN.fullmatch(value["paper_id"]) is not None
        and type(value["source_json_sha256"]) is str
        and HEX64.fullmatch(value["source_json_sha256"]) is not None
    )


def _valid_source_identity(value: object) -> bool:
    if not _exact_keys(value, {"markdown_path", "markdown_sha256", "source_json_sha256"}):
        return False
    assert type(value) is dict
    return (
        type(value["markdown_path"]) is str
        and value["markdown_path"].startswith("papers/")
        and type(value["markdown_sha256"]) is str
        and HEX64.fullmatch(value["markdown_sha256"]) is not None
        and type(value["source_json_sha256"]) is str
        and HEX64.fullmatch(value["source_json_sha256"]) is not None
    )


def _valid_identity_chunk(item: object) -> bool:
    if not _exact_keys(item, {"chunk_id", "page", "paper_id", "text_end", "text_sha256", "text_start"}):
        return False
    assert type(item) is dict
    return (
        type(item["chunk_id"]) is str
        and item["chunk_id"]
        and type(item["page"]) is int
        and type(item["paper_id"]) is str
        and PAPER_ID_PATTERN.fullmatch(item["paper_id"]) is not None
        and type(item["text_end"]) is int
        and type(item["text_start"]) is int
        and type(item["text_sha256"]) is str
        and HEX64.fullmatch(item["text_sha256"]) is not None
    )


def _valid_inventory_rows(rows: object, files: Mapping[str, bytes]) -> bool:
    if type(rows) is not list:
        return False
    expected = _sorted_file_rows([_file_row(name, files[name]) for name in files if name != MANIFEST_NAME])
    if len(rows) != len(expected):
        return False
    for row, want in zip(rows, expected):
        if not _valid_file_row(row) or canonical_bytes(row) != canonical_bytes(want):
            return False
    return True


def _sorted_file_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return sorted(rows, key=lambda item: item["path"])


def _expected_parent_dirs(paths: Mapping[str, bytes] | Iterable[str]) -> set[str]:
    names = paths if isinstance(paths, Mapping) else paths
    parents: set[str] = set()
    for relative in names:
        current = Path(str(relative)).as_posix()
        parent = str(Path(current).parent.as_posix())
        while parent not in {"", "."}:
            parents.add(parent)
            parent = str(Path(parent).parent.as_posix())
    return parents


def _inspect_tree(directory: Path) -> tuple[dict[str, bytes], set[str]] | None:
    if not _is_regular_dir(directory):
        return None
    files: dict[str, bytes] = {}
    dirs: set[str] = set()
    pending = [directory]
    while pending:
        current = pending.pop()
        if current is not directory:
            if current.is_symlink() or not current.is_dir():
                return None
            dirs.add(current.relative_to(directory).as_posix())
        try:
            entries = sorted(current.iterdir(), key=lambda item: item.name)
        except OSError:
            return None
        for item in entries:
            if item.is_symlink():
                return None
            if item.is_dir():
                pending.append(item)
                continue
            if not item.is_file() or _hardlinked(item):
                return None
            files[item.relative_to(directory).as_posix()] = item.read_bytes()
    return files, dirs


def _inventory_bytes(directory: Path) -> dict[str, bytes] | None:
    inspected = _inspect_tree(directory)
    if inspected is None:
        return None
    files, _dirs = inspected
    return files


def _complete_set_match(directory: Path, expected: Mapping[str, bytes]) -> bool:
    inspected = _inspect_tree(directory)
    if inspected is None:
        return False
    files, dirs = inspected
    if set(files) != set(expected) or dirs != _expected_parent_dirs(expected):
        return False
    return all(files[key] == expected[key] for key in expected)


def _bytes_match(expected: Mapping[str, bytes], actual: Mapping[str, bytes] | None) -> bool:
    if actual is None or set(expected) != set(actual):
        return False
    return all(expected[key] == actual[key] for key in expected)


def _record_relative(record_id: str) -> str:
    return f"{KNOWLEDGE_STATE_DIR}/{RECORDS_DIRNAME}/{record_id}"


def _view_relative(view_id: str) -> str:
    return f"{VIEWS_ROOT}/{VIEWS_DIRNAME}/{view_id}"


def _staging_prefix(kind: str, target_id: str) -> str:
    return f"{kind}-{target_id}-"


def _ownership_payload(
    *,
    kind: str,
    target_id: str,
    intended_relative_target: str,
    allowed_payload_set: list[str],
) -> dict[str, Any]:
    return {
        "allowed_payload_set": sorted(allowed_payload_set),
        "intended_relative_target": intended_relative_target,
        "kind": kind,
        "schema": OWNERSHIP_SCHEMA,
        "target_id": target_id,
        "version": 1,
    }


def _valid_ownership_shape(marker: Mapping[str, Any] | None) -> bool:
    if marker is None:
        return False
    allowed = marker.get("allowed_payload_set")
    return (
        set(marker) == {"allowed_payload_set", "intended_relative_target", "kind", "schema", "target_id", "version"}
        and marker.get("schema") == OWNERSHIP_SCHEMA
        and marker.get("version") == 1
        and type(marker.get("kind")) is str
        and type(marker.get("target_id")) is str
        and type(marker.get("intended_relative_target")) is str
        and type(allowed) is list
        and allowed == sorted(str(item) for item in allowed)
        and all(type(item) is str and item and "\\" not in item and ".." not in Path(item).parts for item in allowed)
    )


def _ownership_matches(
    marker: Mapping[str, Any] | None,
    *,
    kind: str,
    target_id: str,
    intended_relative_target: str,
    allowed_payload_set: list[str],
) -> bool:
    expected = _ownership_payload(
        kind=kind,
        target_id=target_id,
        intended_relative_target=intended_relative_target,
        allowed_payload_set=allowed_payload_set,
    )
    return _valid_ownership_shape(marker) and canonical_bytes(marker) == canonical_bytes(expected)


def _list_staging(workspace: Path) -> list[dict[str, Any]]:
    root = _staging_root(workspace)
    rows: list[dict[str, Any]] = []
    if not root.exists() and not root.is_symlink():
        return rows
    if root.is_symlink() or not root.is_dir():
        return [{"relative_path": f"{KNOWLEDGE_STATE_DIR}/{STAGING_DIRNAME}", "status": "unsafe"}]
    for item in sorted(root.iterdir(), key=lambda path: path.name):
        rel = f"{KNOWLEDGE_STATE_DIR}/{STAGING_DIRNAME}/{item.name}"
        if item.is_symlink() or not item.is_dir():
            rows.append({"relative_path": rel, "status": "unsafe"})
            continue
        marker = _load_persisted_object(item / OWNERSHIP_NAME)
        payload = item / PAYLOAD_DIRNAME
        if not _valid_ownership_shape(marker):
            rows.append({"relative_path": rel, "status": "unknown"})
            continue
        assert marker is not None
        inspected = _inspect_tree(payload) if payload.exists() or payload.is_symlink() else ({}, set())
        if payload.exists() and inspected is None:
            rows.append(
                {
                    "kind": marker.get("kind"),
                    "relative_path": rel,
                    "status": "unknown",
                    "target_id": marker.get("target_id"),
                }
            )
            continue
