def _valid_legacy_coverage(value: object) -> bool:
    if not _exact_keys(value, {"exported_chunks", "omitted_pages", "total_chunks", "truncated"}):
        return False
    assert type(value) is dict
    omitted = value.get("omitted_pages")
    return (
