    _publish_record,
    _raise,
    _record_files,
    _records_root,
    _reject_irreplaceable_pointer,
    _require_current_index,
    _set_head,
    _staging_root,
    _validate_document,
    _writing_context,
    canonical_bytes,
    canonical_char_count,
    current_head_record_id,
    inventory_row,
    persisted_bytes,
    publish_managed_file,
    require_hex64,
    require_nonneg_int,
    require_paper_id,
    require_product_workspace,
    sha256_canonical,
    sort_inventory,
