"""Deterministic lightweight workspace backup and fresh-root restore. No Vault reuse."""

from __future__ import annotations

import os
import secrets
import stat
import struct
import zipfile
import zlib
from pathlib import Path
from typing import Any, Mapping

from video_paper_wiki_research.light_index import classify_index_tree
from video_paper_wiki_research.light_library import library_backup_blockers
from video_paper_wiki_research.light_library_state import (
    BACKUP_SCHEMA,
    HISTORY_DIRNAME,
    INDEX_DIRNAME,
    KNOWLEDGE_DIRNAME,
    KNOWLEDGE_STAGING,
    LIBRARY_DIRNAME,
    LIGHT_BACKUP_CONFLICT,
    LIGHT_BACKUP_INVALID,
    LIGHT_WORKSPACE_BUSY,
    LOCKS_DIRNAME,
    MAX_FILE_BYTES,
    MAX_FILES,
    MAX_UNCOMPRESSED_BYTES,
    MAX_ZIP_BYTES,
    RESTORATION_SCHEMA,
    SESSIONS_DIRNAME,
    TRANSACTIONS_DIR,
    WORKFLOW_DIRNAME,
    WORKFLOW_STAGING,
    WORKSPACE_INVALID,
    WORKSPACE_LOCK_NAME,
    HEX64,
    _Busy,
    chain_has_symlink,
    classify_text_file,
