    LIGHT_WORKSPACE_BUSY,
    LOCKS_DIRNAME,
    MAX_FILE_BYTES,
    MAX_FILES,
    MAX_UNCOMPRESSED_BYTES,
    MAX_ZIP_BYTES,
    RESTORATION_SCHEMA,
    SESSIONS_DIRNAME,
    TRANSACTIONS_DIR,
    WORKFLOW_DIRNAME,
    WORKFLOW_STAGING,
    WORKSPACE_INVALID,
    WORKSPACE_LOCK_NAME,
    HEX64,
    _Busy,
